stage_a_raw:
{
  "decisions": [
    {
      "decision": "startup_time_value",
      "evidence": "\"The production quantity on each machine, plus the startup time, cannot exceed the machine's capacity\"",
      "options": [
        "startup_time = 1.0 (charged per product-machine-period startup)",
        "startup_time = 0.0 (no capacity consumed by startup)"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "startup_time = 1.0 (charged per product-machine-period startup)"
    },
    {
      "decision": "setup_linking_big_m",
      "evidence": "\"determining the exact quantity of each product to produce on each machine in each period\" and \"production and startup decisions must be binary\"",
      "options": [
        "x[m,p,t] <= capacity[m] * y[m,p,t]",
        "x[m,p,t] <= 1.0e6 * y[m,p,t]"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "x[m,p,t] <= capacity[m] * y[m,p,t]"
    },
    {
      "decision": "startup_indicator_upper_bound",
      "evidence": "\"If a machine is used for production in a period but was not used in the previous period, a startup cost is incurred\"",
      "options": [
        "only z >= y[t] - y[t-1] (z may be 1 even without a real startup)",
        "add z <= y[t] and z >= y[t] - y[t-1] (z exactly indicates a startup)"
      ],
      "plausibility": [
        0.55,
        0.45
      ],
      "majority_option": "only z >= y[t] - y[t-1] (z may be 1 even without a real startup)"
    },
    {
      "decision": "startup_logic_period_zero",
      "evidence": "\"If a machine is used for production in a period but was not used in the previous period, a startup cost is incurred\"",
      "options": [
        "z[m,p,0] >= y[m,p,0] (first-period use counts as a startup)",
        "no startup constraint in period 0 (z free / zero)"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "z[m,p,0] >= y[m,p,0] (first-period use counts as a startup)"
    },
    {
      "decision": "inventory_balance_orientation",
      "evidence": "\"total production of each product across all machines, plus any inventory carried over from the previous period, minus any backlog from the previous period, equals the demand ... plus any inventory carried forward, minus any backlogged demand\"",
      "options": [
        "I[t-1] + prod - B[t-1] == demand + I[t] - B[t]",
        "prod + I[t-1] + B[t] == demand + I[t] + B[t-1]"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "I[t-1] + prod - B[t-1] == demand + I[t] - B[t]"
    },
    {
      "decision": "demand_satisfaction_constraint",
      "evidence": "\"while meeting customer demand for each product in each period\"",
      "options": [
        "balance equality alone (backlog allowed, demand may be deferred)",
        "add explicit demand_satisfaction constraint requiring cumulative production >= cumulative demand"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "balance equality alone (backlog allowed, demand may be deferred)"
    }
  ]
}
